            <div style="font-weight:700;color:var(--ks-ink);margin-top:8px"><span class="chem-tok" data-role="chain">ziklo</span>butanoa (<span class="chem">${Z("C4H8")}</span>) · eraztun itxia (<span class="chem">2 H</span> gutxiago)</div>
